          var insSpan = c.inserted ? '<span style="' + insStyle + '">' + esc(c.inserted) + '</span>' : "";
          var inner = (c.delFirst === false) ? (insSpan + delSpan) : (delSpan + insSpan);
          if (s.verdict === "revise") {
