            '<div style="font:500 10.5px/1.5 Inter,sans-serif;color:#7c2d12;margin-bottom:6px;">Your decisions make these necessary in text nobody redlined. Use <b>✎ Edit text</b> on the paragraph to write them in, or make them in Word afterwards.</div>' +
            conforming.map(function (e) {
