    }
    box.innerHTML =
      '<div style="padding:16px 22px;background:linear-gradient(135deg,#1e3a8a 0%,#1565c0 100%);color:#fff;display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #c9a227;flex-shrink:0;">' +
        '<div><div style="font-size:10px;font-weight:800;opacity:0.85;text-transform:uppercase;letter-spacing:1.6px;">⚖️ Review redlines</div>' +
