        '<div data-adj-sub style="font-size:10.5px;opacity:0.82;margin-top:3px;font-weight:600;"></div></div>' +
        '<button id="tpAdjCloseBtn" style="background:rgba(255,255,255,0.18);border:1px solid rgba(255,255,255,0.4);color:#fff;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer;border-radius:0;">✕ Close</button>' +
      '</div>' +
      '<div data-adj-posture style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;padding:9px 22px;background:#f1f5f9;border-bottom:1px solid #e2e8f0;flex-shrink:0;"></div>' +
      '<div data-adj-scroll style="flex:1;overflow-y:auto;padding:16px 22px;background:#fafaf5;"></div>' +
      '<div data-adj-foot style="flex-shrink:0;border-top:1px solid #e2e8f0;background:#fff;padding:10px 16px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;"></div>';
    overlay.appendChild(box);
    document.body.appendChild(overlay);

    var scrollHost = box.querySelector("[data-adj-scroll]");
    var footEl = box.querySelector("[data-adj-foot]");
    var postureEl = box.querySelector("[data-adj-posture]");
    var subEl = box.querySelector("[data-adj-sub]");
    var tallyEl = null, previewEl = null;
    // The rows carry the verdicts, so almost any change means a full body
