  var box = document.createElement("div");
  box.style.cssText =
    "background:#fff; width:380px; max-width:92%; border:1px solid #e2e8f0; box-shadow:0 20px 50px rgba(0,0,0,0.25); padding:0; overflow:hidden; font-family:Inter,system-ui,sans-serif;";
  box.innerHTML =
    '<div style="background:linear-gradient(135deg,#1565c0 0%,#0d47a1 100%); padding:16px 20px; color:#fff;">' +
