    '    <button id="noTmplGoCompare" style="width:100%; padding:14px; background:#fff; color:#0f172a; border:2px solid #1565c0; font-weight:800; font-size:12px; letter-spacing:1px; text-transform:uppercase; cursor:pointer; transition:all 0.15s;">⚖️ Compare Against Another Document</button>' +
    '    <button id="noTmplCancel" style="width:100%; padding:10px; background:none; color:#64748b; border:none; font-size:11px; font-weight:600; cursor:pointer;">Cancel</button>' +
